  UnitExperience.RecordHit(enemy,"B",truck);truck.Restore(truck.Capacity);truck.UnderFire=false;truck.BeginEnter(city);Check(UnitExperience.Ensure(truck).TryPromote(),"transport survivor can grow");Near(UnitExperience.OutputMultiplier(truck),1,"transport gains no attack capability");Near(UnitExperience.IncomingMultiplier(truck),.96f,"transport gains defense");truck.BeginExit();
  own.Restore(own.Capacity);own.transform.position=Vector3.zero;own.Motor.Stop();UnitExperience.RecordHit(own,"A",enemy);Check(TacticalDetachment.Split(w,own,DetachmentKind.Feint).accepted,"veteran splitting works");var child=w.units.First(u=>u!=own&&TacticalDetachment.Family(own,u));Check(UnitExperience.Ensure(child).Level==xp.Level&&!UnitExperience.Ensure(child).PendingPromotion,"split inherits rank without copying unclaimed promotion");child.transform.position=own.transform.position;Check(TacticalDetachment.Merge(w,child,own).accepted,"veteran merge works");Check(xp.Level==4,"merge preserves identical veteran ranks");
