  new GameObject("audit network exclusion").AddComponent<LocalPvpSession>();Near(UnitExperience.OutputMultiplier(own),1,"network growth excluded");Near(UnitExperience.IncomingMultiplier(own),1,"network defense unchanged");Check(UnitExperience.Ensure(own)==null,"network adds no growth components");LocalPvpSession.CloseActive();
